html,body{min-height:100%;}
body.aj08-static{margin:0;overflow-x:hidden;}
body.aj08-static .open-index,body.aj08-static .sheet{display:none!important;}
.aj08-route-modal{position:fixed;inset:0;z-index:9999;display:none;align-items:flex-end;justify-content:center;padding:18px;background:rgba(15,23,42,.52)}
.aj08-route-modal.open{display:flex}.aj08-route-card{width:min(100%,520px);border-radius:18px;padding:18px;background:#fff;box-shadow:0 24px 60px rgba(0,0,0,.25)}
.aj08-route-card .aj08-kicker{margin:0 0 7px;color:#b88932;font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.aj08-route-card h2{margin:0 0 8px;color:#10233f;font-size:20px}.aj08-route-card p{margin:0 0 12px;color:#667085;font-size:13px;line-height:1.5}.aj08-route-card code{display:block;overflow-wrap:anywhere;margin:0 0 14px;padding:10px 12px;border-radius:10px;background:#eef2f6;color:#10233f;font:700 12px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace}.aj08-route-card button{width:100%;min-height:46px;border:0;border-radius:11px;background:#10233f;color:#fff;font-weight:800;cursor:pointer}
.aj08-static-note{position:fixed;z-index:80;right:12px;top:12px;max-width:min(260px,calc(100vw - 24px));padding:7px 10px;border-radius:999px;background:rgba(17,24,39,.86);color:#fff;font-size:10px;font-weight:800;pointer-events:none;box-shadow:0 6px 18px rgba(0,0,0,.15)}
@media(max-width:600px){.aj08-static-note{top:auto;right:10px;bottom:10px;max-width:calc(100vw - 20px)}}

/* Compatibilidade da composição modular com o DOM das telas estáticas. */
#screen-root,.screen-runtime,[data-screen-root]{min-height:100dvh}
.screen-runtime{width:100%}
.screen-slot,screen-section{display:contents}
.screen-runtime .prototype-screen .screen-slot--main{display:block;width:min(100%,720px);margin:0 auto;padding:22px 16px 28px}
.screen-runtime .prototype-screen .screen-slot--main screen-section{display:block}
.screen-runtime .prototype-screen .screen-slot--main screen-section+screen-section{margin-top:12px}
.screen-loading,.screen-error{display:block;width:min(100% - 32px,720px);margin:32px auto;padding:18px;border:1px solid var(--line);border-radius:14px;background:#fff;line-height:1.55}
.section-runtime-warning{display:block;margin:12px;padding:12px;border:1px dashed #b8c2cf;border-radius:12px;background:#fff}
[data-studio-toolbar]{display:flex!important}


:root{--ui-navy:#10233f;--ui-blue:#2563eb;--ui-ink:#18283c;--ui-muted:#65758a;--ui-line:#dce5f0;--ui-bg:#f2f6fb;--ui-success:#118563}
*{box-sizing:border-box}html,body{margin:0!important;min-width:0!important;background:var(--ui-bg)!important;color:var(--ui-ink)!important;font-family:Arial,'Segoe UI',sans-serif!important}
.demo-app{background:#f2f6fb;min-height:100dvh;padding-bottom:86px;color:var(--ui-ink);font-size:14px;max-width:660px;margin:auto}
.demo-header{position:sticky;top:0;background:var(--ui-navy);color:white;z-index:3;padding:17px 18px 15px;box-shadow:0 3px 12px #11213c22}
.demo-header .upper{display:flex;align-items:center;gap:10px;font-size:12px;opacity:.85;margin-bottom:9px}
.demo-header h1{font-size:23px;margin:0 0 4px;color:white}.demo-header p{font-size:11px;margin:0;opacity:.85}
.demo-body{padding:19px 15px;display:grid;gap:14px}
.demo-pill{font-size:10px;font-weight:800;color:#205dba;background:#e8f1ff;border:1px solid #cfe0fa;display:inline-flex;border-radius:999px;padding:6px 10px;width:fit-content}
.demo-box{border:1px solid #dfe6ef;background:white;border-radius:14px;padding:17px;box-shadow:0 5px 17px #16345c09}
.demo-box h2{font-size:16px;margin:0 0 8px;color:#172b48}.demo-box h3{font-size:14px;margin:0 0 8px}
.demo-box p{font-size:12px;color:#62748b;line-height:1.65;margin:6px 0}
.demo-row{display:flex;align-items:center;gap:9px;justify-content:space-between;flex-wrap:wrap}
.demo-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.demo-tile{border:1px solid #dce6f3;border-radius:12px;background:#f9fbfe;padding:15px 12px;min-height:86px}
.demo-tile strong{display:block;font-size:13px;color:#1a3151}.demo-tile small{display:block;margin-top:6px;color:#63738a;font-size:11px;line-height:1.5}
.demo-btn{width:100%;border:0;background:#2563eb!important;color:#fff!important;border-radius:10px;padding:12px 15px;display:block;text-align:center;font-size:12px;font-weight:800}
.demo-btn-outline{background:white!important;color:#245caa!important;border:1px solid #b8d0f1!important}
.demo-lock{color:#966b24;border:1px solid #f2dca7;background:#fff8e7;border-radius:10px;padding:12px 14px;font-size:12px;line-height:1.5}
.demo-success{color:#137654;border:1px solid #b5e5d2;background:#eafaf1;border-radius:10px;padding:12px 14px;font-size:12px;line-height:1.5}
.demo-muted{font-size:10px!important;color:#8290a3!important}
.demo-bottom{position:fixed;bottom:0;left:0;right:0;max-width:660px;margin:auto;display:flex;justify-content:space-around;border-top:1px solid #e0e7f0;background:#fff;padding:13px 8px 17px;z-index:2}
.demo-bottom span{font-size:11px;color:#677b92;text-align:center;flex:1}.demo-bottom .selected{color:#205bc2;font-weight:800}
.demo-cta{background:linear-gradient(115deg,#10233f,#234f87);color:#fff;border-radius:13px;padding:17px}
.demo-cta h2{color:#fff;margin:0 0 7px}.demo-cta p{color:#cfdef2;margin:0 0 12px}
.demo-modal-cover{background:rgba(7,23,43,.45);padding:22px 8px 40px;margin:-19px -15px 0;min-height:420px;display:grid;align-content:center}
.demo-modal{background:#fff;border-radius:16px;padding:21px;box-shadow:0 25px 60px #0004}
.demo-modal h2{font-size:20px}.demo-modal p{line-height:1.6}
.demo-field{display:grid;gap:6px;color:#364861;font-size:11px;margin-top:10px}.demo-field input{width:100%;border:1px solid #dbe4ef;border-radius:9px;padding:12px;background:#fff;color:#19283c}
@media(max-width:420px){.demo-header h1{font-size:20px}.demo-grid{grid-template-columns:1fr 1fr}}
